public function toggleOptions(int $options, ?bool $state = null): static
{
    $self = $this->copyIfImmutable();

    if ($state === null) {
        $state = ($this->options & $options) !== $options;
    }

    return $self->setOptions(
        $state ?
        $this->options | $options :
        $this->options & ~$options,
